#if os(iOS)
import SwiftUI
import StrandDesign

/// Renders one `LocalCoachCard` as a flat widget inside a Coach answer: one surface, a hairline, an eyebrow with the
/// metric glyph, a delta pill, a hero number, the trend chart where a series exists and a three-column stat strip.
/// Every figure is read from the card payload; nothing here is generated by the language model. Missing values draw
/// as an em dash, never as zero.
struct LocalCoachCardView: View {
    let card: LocalCoachCard
    @AppStorage(UnitPrefs.effortScaleKey) private var effortScaleRaw = EffortScale.whoop.rawValue
    private var effortScale: EffortScale { UnitPrefs.resolveEffortScale(effortScaleRaw) }

    var body: some View {
        content
            .accessibilityElement(children: .combine)
            .accessibilityLabel(Text(accessibilityText))
            .accessibilityIdentifier("coach.card.\(card.kind)")
    }

    @ViewBuilder private var content: some View {
        switch card {
        case .recovery(let value): CoachRecoveryCard(card: value)
        case .sleep(let value): CoachSleepCard(card: value)
        case .trend(let value): CoachTrendCard(card: value, effortScale: effortScale)
        case .effort(let value): CoachEffortCard(card: value, effortScale: effortScale)
        case .workouts(let value): CoachWorkoutsCard(card: value, effortScale: effortScale)
        case .stats(let value): CoachStatsCard(card: value)
        }
    }

    /// One spoken sentence per card, on the same display scale the card shows.
    private var accessibilityText: String {
        let date = card.day.map { LocalCoachCardFormat.dayLabel($0) } ?? ""
        let stale = card.isStale ? ", stale" : ""
        switch card {
        case .recovery(let value):
            return "Recovery, \(date)\(stale). Score \(LocalCoachCardFormat.whole(value.score, unit: "out of 100")), HRV \(LocalCoachCardFormat.whole(value.hrvMs, unit: "milliseconds")), resting heart rate \(LocalCoachCardFormat.whole(value.restingHr, unit: "beats per minute")), sleep \(LocalCoachCardFormat.duration(minutes: value.sleepMinutes))."
        case .sleep(let value):
            return "Sleep, \(date)\(stale). Total \(LocalCoachCardFormat.duration(minutes: value.totalMinutes)), deep \(LocalCoachCardFormat.duration(minutes: value.deepMinutes)), REM \(LocalCoachCardFormat.duration(minutes: value.remMinutes)), light \(LocalCoachCardFormat.duration(minutes: value.lightMinutes)), efficiency \(LocalCoachCardFormat.whole(value.efficiencyPercent, unit: "percent"))."
        case .trend(let value):
            let format = CoachTrendFormat(metricID: value.metricID, effortScale: effortScale)
            return "\(format.title(value.title)) trend, newest \(date)\(stale). Latest \(format.text(value.latest)) \(format.unit(value.unit)), average \(format.text(value.average)), low \(format.text(value.minimum)), high \(format.text(value.maximum)), \(value.points.count) observed days."
        case .effort(let value):
            let scaled = value.value.map { UnitFormatter.effortDisplay($0, scale: effortScale) } ?? "not recorded"
            return "Strain, \(date)\(stale). \(scaled) out of \(UnitFormatter.effortScaleMax(effortScale)). \(value.workoutCount.map { "\($0) workouts in \(value.windowDays) days" } ?? "Workout count not available")."
        case .workouts(let value):
            let rows = value.items.map { "\($0.sport), \(LocalCoachCardFormat.startLabel($0.startTs)), \(LocalCoachCardFormat.duration(seconds: $0.durationS))" }
            return "Recent workouts, newest \(date). " + rows.joined(separator: "; ") + "."
        case .stats(let value):
            return "\(value.title), \(date)\(stale). " + value.items.map { "\($0.label) \(LocalCoachCardFormat.displayValue($0.value))" }.joined(separator: ", ") + "."
        }
    }
}

// MARK: - Flat widget chrome

private enum CoachWidgetMetrics {
    static let radius: CGFloat = 22
    static let chartHeight: CGFloat = 96
}

/// The one surface every Coach record card draws on: the card fill, a hairline, a 22pt radius. No wash, no gradient.
private struct CoachWidget<Content: View>: View {
    let symbol: String
    let title: String
    let tint: DomainTint
    var trailing: EyebrowTrailing = .none
    @ViewBuilder let content: () -> Content

    var body: some View {
        let shape = RoundedRectangle(cornerRadius: CoachWidgetMetrics.radius, style: .continuous)
        VStack(alignment: .leading, spacing: 0) {
            SectionEyebrow(title: title, systemImage: symbol, tint: tint, trailing: trailing)
            content()
        }
        .padding(EdgeInsets(top: 16, leading: 16, bottom: 14, trailing: 16))
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(shape.fill(StrandPalette.card))
        .overlay(shape.strokeBorder(StrandPalette.hairline, lineWidth: 1))
    }
}

/// A tinted pill in the eyebrow's trailing slot.
private func coachPill(_ text: Text, tint: Color) -> EyebrowTrailing {
    .custom(AnyView(CoachTintPill(text: text, tint: tint)))
}

/// A big figure with its unit beside it: "58 ms", or "7 h 42 m" as two figure and unit pairs. A missing figure reads
/// "—" in the tertiary ink.
private struct CoachHero: View {
    let parts: [(value: String, unit: String?)]
    @ScaledMetric(relativeTo: .largeTitle) private var size: CGFloat = 42
    @ScaledMetric(relativeTo: .body) private var unitSize: CGFloat = 17

    var body: some View {
        HStack(alignment: .firstTextBaseline, spacing: 6) {
            ForEach(Array(parts.enumerated()), id: \.offset) { _, part in
                Text(part.value)
                    .font(.system(size: size, weight: .semibold).monospacedDigit())
                    .tracking(-size * 0.024)
                    .foregroundStyle(part.value == WidgetMetrics.missingValue
                                     ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                    .lineLimit(1).minimumScaleFactor(0.5)
                if let unit = part.unit, part.value != WidgetMetrics.missingValue {
                    Text(unit)
                        .font(.system(size: unitSize, weight: .medium))
                        .foregroundStyle(StrandPalette.textSecondary)
                        .lineLimit(1).minimumScaleFactor(0.6)
                        .padding(.trailing, 2)
                }
            }
        }
        .padding(.top, 10)
    }
}

/// The record's real date (and a Stale pill when the newest record is older than the window read), then any detail,
/// under the hero. Every card names the record it describes.
private struct CoachRecordLine: View {
    let date: String?
    let isStale: Bool
    var detail: String?

    private var text: String { [date, detail].compactMap { $0 }.joined(separator: " · ") }

    var body: some View {
        if isStale || !text.isEmpty {
            ViewThatFits(in: .horizontal) {
                HStack(spacing: 8) { items }
                VStack(alignment: .leading, spacing: 4) { items }
            }
            .padding(.top, 2)
        }
    }

    @ViewBuilder private var items: some View {
        if isStale { StatePill("Stale", tone: .warning, showsDot: false) }
        if !text.isEmpty {
            Text(text).coachFont(13, .regular, relativeTo: .footnote)
                .foregroundStyle(StrandPalette.textTertiary)
                .fixedSize(horizontal: false, vertical: true)
        }
    }
}

private struct CoachStat: Identifiable {
    let id: Int
    let label: LocalizedStringKey
    let value: String
    var unit: String?
    /// A stage colour shown as a small dot before the label (sleep stages).
    var dot: Color?
}

/// Low | Average | High, or any other three facts: a hairline above, hairline dividers between equal columns. Stacked
/// at accessibility sizes and wherever a column would truncate.
private struct CoachStatStrip: View {
    let items: [CoachStat]
    @Environment(\.dynamicTypeSize) private var typeSize

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Rectangle().fill(StrandPalette.hairline).frame(height: 1).accessibilityHidden(true)
            Group {
                if typeSize.isAccessibilitySize {
                    stacked
                } else {
                    ViewThatFits(in: .horizontal) {
                        columns
                        stacked
                    }
                }
            }
            .padding(.top, 11)
        }
        .padding(.top, 12)
    }

    private var columns: some View {
        HStack(alignment: .top, spacing: 0) {
            ForEach(items) { item in
                if item.id != items.first?.id {
                    Rectangle().fill(StrandPalette.hairline).frame(width: 1).accessibilityHidden(true)
                }
                column(item, fitsWhole: true)
                    .padding(.leading, item.id == items.first?.id ? 0 : 12)
                    .padding(.trailing, item.id == items.last?.id ? 0 : 8)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
        .fixedSize(horizontal: false, vertical: true)
    }

    private var stacked: some View {
        VStack(alignment: .leading, spacing: NoopMetrics.space3) {
            ForEach(items) { item in
                if item.id != items.first?.id {
                    Rectangle().fill(StrandPalette.hairline).frame(height: 1).accessibilityHidden(true)
                }
                column(item, fitsWhole: false).frame(maxWidth: .infinity, alignment: .leading)
            }
        }
    }

    /// `fitsWhole` makes the column report the full width of its label and value, so `ViewThatFits` moves on to the
    /// stacked layout instead of truncating one of them.
    private func column(_ item: CoachStat, fitsWhole: Bool) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack(spacing: 5) {
                if let dot = item.dot {
                    Circle().fill(dot).frame(width: 6, height: 6).accessibilityHidden(true)
                }
                Text(item.label).coachFont(12, .regular, relativeTo: .caption)
                    .foregroundStyle(StrandPalette.textTertiary)
                    .lineLimit(1)
            }
            HStack(alignment: .firstTextBaseline, spacing: 2) {
                Text(item.value).coachFont(17, .semibold, relativeTo: .body, digits: true)
                    .foregroundStyle(item.value == WidgetMetrics.missingValue
                                     ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                    .lineLimit(1)
                if let unit = item.unit, item.value != WidgetMetrics.missingValue {
                    Text(unit).coachFont(12.5, .medium, relativeTo: .caption)
                        .foregroundStyle(StrandPalette.textSecondary)
                        .lineLimit(1)
                }
            }
            .fixedSize(horizontal: fitsWhole, vertical: false)
        }
    }
}

/// The chart a series earns: the #55 trend chart, quiet, with the newest point capped in the metric's colour.
private struct CoachSeriesChart: View {
    let points: [TrendPoint]
    let gradient: Gradient
    let valueRange: ClosedRange<Double>
    let cap: Color
    let label: String
    let valueFormat: (Double) -> String

    var body: some View {
        TrendChart(points: points, gradient: gradient, valueRange: valueRange, showsArea: true,
                   height: CoachWidgetMetrics.chartHeight, showsHover: false, valueFormat: valueFormat,
                   accessibilityLabel: label, nowCapColor: cap, yDomain: coachChartDomain(points),
                   xAxisLabelCount: 3)
            .accessibilityHidden(true)
            .padding(.top, 10)
    }
}

/// Fit the axis to the observed range with headroom, so a steady series is not drawn as a flat line.
private func coachChartDomain(_ points: [TrendPoint]) -> ClosedRange<Double> {
    let values = points.map(\.value)
    guard let low = values.min(), let high = values.max() else { return 0...1 }
    let pad = max((high - low) * 0.2, 0.5)
    return (low - pad)...(high + pad)
}

// MARK: - Recovery

private struct CoachRecoveryCard: View {
    let card: LocalCoachCard.Recovery

    private var trailing: EyebrowTrailing {
        guard let score = card.score else { return .none }
        return coachPill(Text(verbatim: RecoveryBands.word(for: score)), tint: RecoveryBands.color(for: score))
    }

    var body: some View {
        CoachWidget(symbol: "heart.fill", title: String(localized: "Recovery"), tint: .recovery(score: card.score), trailing: trailing) {
            CoachHero(parts: [(LocalCoachCardFormat.whole(card.score), "%")])
            CoachRecordLine(date: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale)
            CoachStatStrip(items: [
                CoachStat(id: 0, label: "HRV", value: LocalCoachCardFormat.whole(card.hrvMs), unit: "ms"),
                CoachStat(id: 1, label: "Resting HR", value: LocalCoachCardFormat.whole(card.restingHr), unit: "bpm"),
                CoachStat(id: 2, label: "Sleep", value: LocalCoachCardFormat.duration(minutes: card.sleepMinutes))
            ])
        }
    }
}

// MARK: - Sleep

private struct CoachSleepCard: View {
    let card: LocalCoachCard.Sleep

    private var stages: [(label: LocalizedStringKey, minutes: Double?, color: Color)] {
        [("Deep", card.deepMinutes, StrandPalette.sleepDeep),
         ("REM", card.remMinutes, StrandPalette.sleepREM),
         ("Light", card.lightMinutes, StrandPalette.sleepLight)]
    }

    private var hero: [(value: String, unit: String?)] {
        guard let minutes = card.totalMinutes, minutes.isFinite, minutes >= 0 else { return [("—", nil)] }
        let total = Int(minutes.rounded())
        return total < 60 ? [(String(total), "m")] : [(String(total / 60), "h"), (String(total % 60), "m")]
    }

    private var chartPoints: [TrendPoint] {
        card.recentNights.compactMap { night in
            LocalCoachWindow.date(night.day).map { TrendPoint(date: $0, value: night.value / 60) }
        }
    }

    private var trailing: EyebrowTrailing {
        guard let efficiency = card.efficiencyPercent else { return .none }
        return coachPill(Text("\(LocalCoachCardFormat.whole(efficiency, unit: "%")) efficiency"),
                         tint: StrandPalette.sleepAccent)
    }

    var body: some View {
        CoachWidget(symbol: "moon.stars.fill", title: String(localized: "Sleep"), tint: .sleep, trailing: trailing) {
            CoachHero(parts: hero)
            CoachRecordLine(date: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale,
                            detail: card.recentNights.count > 1
                                ? String(localized: "\(card.recentNights.count) recorded nights") : nil)
            if chartPoints.count > 1 {
                CoachSeriesChart(points: chartPoints, gradient: StrandPalette.restGradient,
                                 valueRange: coachChartDomain(chartPoints), cap: StrandPalette.sleepAccent,
                                 label: String(localized: "Sleep trend"),
                                 valueFormat: { LocalCoachCardFormat.oneDecimal($0) })
            }
            if stages.contains(where: { ($0.minutes ?? 0) > 0 }) {
                CoachStageBar(stages: stages.map { (minutes: $0.minutes, color: $0.color) })
                    .padding(.top, 12)
            }
            CoachStatStrip(items: stages.enumerated().map { index, stage in
                CoachStat(id: index, label: stage.label, value: LocalCoachCardFormat.duration(minutes: stage.minutes),
                          dot: stage.color)
            })
        }
    }
}

/// Deep / REM / light as proportional capsule segments. Only stages that were recorded are drawn.
private struct CoachStageBar: View {
    let stages: [(minutes: Double?, color: Color)]

    var body: some View {
        let present = stages.compactMap { stage -> (Double, Color)? in
            guard let minutes = stage.minutes, minutes > 0 else { return nil }
            return (minutes, stage.color)
        }
        let total = present.reduce(0) { $0 + $1.0 }
        GeometryReader { proxy in
            let gaps = CGFloat(max(0, present.count - 1)) * 2
            HStack(spacing: 2) {
                ForEach(present.indices, id: \.self) { index in
                    RoundedRectangle(cornerRadius: 3, style: .continuous)
                        .fill(present[index].1)
                        .frame(width: max(3, (proxy.size.width - gaps) * present[index].0 / total))
                }
            }
        }
        .frame(height: 8)
        .clipShape(Capsule(style: .continuous))
        .accessibilityHidden(true)
    }
}

// MARK: - Trend

/// Per-metric number formatting. Effort is stored 0...100 and shown on the user's display scale.
private struct CoachTrendFormat {
    let metricID: String
    let effortScale: EffortScale

    var isEffort: Bool { metricID == "strain" }

    func value(_ stored: Double) -> Double { isEffort ? UnitFormatter.effortValue(stored, scale: effortScale) : stored }

    func text(_ stored: Double?) -> String {
        guard let stored else { return "—" }
        switch metricID {
        case "strain", "sleep": return LocalCoachCardFormat.oneDecimal(value(stored))
        default: return LocalCoachCardFormat.whole(stored)
        }
    }

    func unit(_ payloadUnit: String) -> String { isEffort ? "of \(UnitFormatter.effortScaleMax(effortScale))" : payloadUnit }

    /// What the card calls the metric: Strain, as Today words it. The card keeps the record's own title, which is
    /// also what the model is told.
    func title(_ recordTitle: String) -> String { isEffort ? "Strain" : recordTitle }

    var tint: DomainTint {
        switch metricID {
        case "recovery": return .custom(StrandPalette.recoveryHigh)
        case "strain": return .strain
        case "sleep": return .sleep
        case "hrv": return .hrv
        default: return .heart
        }
    }

    var symbol: String {
        switch metricID {
        case "recovery": return "heart.fill"
        case "strain": return "flame.fill"
        case "sleep": return "moon.stars.fill"
        case "hrv": return "waveform.path.ecg"
        default: return "heart.fill"
        }
    }

    /// The newest value against the window's average, as the pill says it: an arrow and the size of the gap in the
    /// metric's own precision. Nil when either figure is missing or the gap rounds to nothing.
    func delta(latest: Double?, average: Double?) -> (arrow: String, amount: String, tint: Color)? {
        guard let latest, let average, latest.isFinite, average.isFinite else { return nil }
        let gap = value(latest) - value(average)
        let wholeNumbers = metricID != "strain" && metricID != "sleep"
        let rounded = wholeNumbers ? gap.rounded() : (gap * 10).rounded() / 10
        guard rounded != 0 else { return nil }
        let up = rounded > 0
        let magnitude = abs(rounded)
        let amount = wholeNumbers ? LocalCoachCardFormat.whole(magnitude) : LocalCoachCardFormat.oneDecimal(magnitude)
        let tint: Color
        switch metricID {
        case "strain": tint = StrandPalette.strainAccent
        case "rhr": tint = up ? StrandPalette.statusCritical : StrandPalette.statusPositive
        default: tint = up ? StrandPalette.statusPositive : StrandPalette.statusCritical
        }
        return (up ? "▲" : "▼", amount, tint)
    }
}

private struct CoachTrendCard: View {
    let card: LocalCoachCard.Trend
    let effortScale: EffortScale

    private var format: CoachTrendFormat { CoachTrendFormat(metricID: card.metricID, effortScale: effortScale) }

    private var chartPoints: [TrendPoint] {
        card.points.compactMap { point in
            LocalCoachWindow.date(point.day).map { TrendPoint(date: $0, value: format.value(point.value)) }
        }
    }

    private var gradient: Gradient {
        card.metricID == "recovery" ? StrandPalette.recoveryGradient
            : Gradient(colors: [format.tint.accent.opacity(0.55), format.tint.accent])
    }

    private var trailing: EyebrowTrailing {
        guard let delta = format.delta(latest: card.latest, average: card.average) else { return .none }
        return coachPill(Text("\(delta.arrow) \(delta.amount) vs avg"), tint: delta.tint)
    }

    var body: some View {
        CoachWidget(symbol: format.symbol, title: "\(format.title(card.title)) trend", tint: format.tint,
                    trailing: trailing) {
            CoachHero(parts: [(format.text(card.latest), format.unit(card.unit))])
            CoachRecordLine(date: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale,
                            detail: String(localized: "\(card.points.count) recorded days"))
            if chartPoints.count > 1 {
                CoachSeriesChart(points: chartPoints, gradient: gradient,
                                 valueRange: card.metricID == "recovery" ? 0...100 : coachChartDomain(chartPoints),
                                 cap: format.tint.accent, label: "\(format.title(card.title)) trend",
                                 valueFormat: { format.text($0) })
            }
            CoachStatStrip(items: [
                CoachStat(id: 0, label: "Low", value: format.text(card.minimum)),
                CoachStat(id: 1, label: "Average", value: format.text(card.average)),
                CoachStat(id: 2, label: "High", value: format.text(card.maximum))
            ])
        }
    }
}

// MARK: - Strain

private struct CoachEffortCard: View {
    let card: LocalCoachCard.Effort
    let effortScale: EffortScale

    private var band: String? {
        card.value.map { StrainScale.band(UnitFormatter.effortValue($0, scale: effortScale)).title }
    }

    private var trailing: EyebrowTrailing {
        guard let band else { return .none }
        return coachPill(Text(verbatim: band), tint: StrandPalette.strainAccent)
    }

    var body: some View {
        CoachWidget(symbol: "flame.fill", title: String(localized: "Strain"), tint: .strain, trailing: trailing) {
            CoachHero(parts: [(card.value.map { UnitFormatter.effortDisplay($0, scale: effortScale) } ?? "—",
                               "of \(UnitFormatter.effortScaleMax(effortScale))")])
            CoachRecordLine(date: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale)
            CoachStatStrip(items: [
                CoachStat(id: 0, label: "Workouts", value: card.workoutCount.map(String.init) ?? "—",
                          unit: card.workoutCount == nil ? nil : "in \(card.windowDays) d"),
                CoachStat(id: 1, label: "Load", value: band ?? "—")
            ])
        }
    }
}

// MARK: - Workouts

private struct CoachWorkoutsCard: View {
    let card: LocalCoachCard.Workouts
    let effortScale: EffortScale

    /// A list of workouts has no single record date; show the window that was read when it is known.
    private var windowLabel: String? {
        guard let from = card.windowFrom, let through = card.windowThrough else { return nil }
        return LocalCoachCardFormat.windowLabel(from: from, through: through)
    }

    var body: some View {
        CoachWidget(symbol: "figure.run", title: String(localized: "Recent workouts"), tint: .workout,
                    trailing: .record(date: windowLabel, isStale: card.isStale)) {
            VStack(spacing: 0) {
                ForEach(Array(card.items.enumerated()), id: \.offset) { index, item in
                    if index > 0 {
                        Rectangle().fill(StrandPalette.hairline).frame(height: 1).accessibilityHidden(true)
                    }
                    CoachWorkoutRow(item: item, effortScale: effortScale)
                        .padding(.vertical, NoopMetrics.space3)
                }
            }
            .padding(.top, NoopMetrics.space1)
        }
    }
}

private struct CoachWorkoutRow: View {
    let item: LocalCoachCard.WorkoutItem
    let effortScale: EffortScale

    /// One line while it fits. When the text grows, the figures drop under the heading and the heading wraps, so no
    /// sport, time or number is ever cut short.
    var body: some View {
        ViewThatFits(in: .horizontal) {
            HStack(spacing: NoopMetrics.space3) {
                icon
                heading
                Spacer(minLength: NoopMetrics.space1)
                HStack(spacing: NoopMetrics.space4) {
                    bpmFigure(leading: false)
                    effortFigure(leading: false)
                }
            }
            VStack(alignment: .leading, spacing: NoopMetrics.space2) {
                HStack(alignment: .top, spacing: NoopMetrics.space3) {
                    icon
                    heading.fixedSize(horizontal: false, vertical: true)
                }
                // Side by side while they fit, one above the other at the largest text sizes.
                ViewThatFits(in: .horizontal) {
                    HStack(spacing: NoopMetrics.space5) {
                        bpmFigure(leading: true)
                        effortFigure(leading: true)
                    }
                    VStack(alignment: .leading, spacing: NoopMetrics.space2) {
                        bpmFigure(leading: true)
                        effortFigure(leading: true)
                    }
                }
                .padding(.leading, NoopMetrics.iconCircleDiameter + NoopMetrics.space3)
            }
            // Fills the card's width so the row starts at its leading edge; without it the card centres a stacked row.
            .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private var icon: some View {
        Image(systemName: sportSymbol(item.sport)).font(StrandFont.body)
            .foregroundStyle(StrandPalette.strainAccent)
            .frame(width: NoopMetrics.iconCircleDiameter, height: NoopMetrics.iconCircleDiameter)
            .background(StrandPalette.strainAccent.opacity(0.14), in: Circle())
    }

    /// The sport and when it happened. Single lines in the one-line row; the stacked row lets them wrap.
    private var heading: some View {
        VStack(alignment: .leading, spacing: 2) {
            Text(item.sport).coachFont(16.5, .semibold, relativeTo: .body)
                .foregroundStyle(StrandPalette.textPrimary)
            Text("\(LocalCoachCardFormat.startLabel(item.startTs)) · \(LocalCoachCardFormat.duration(seconds: item.durationS))")
                .coachFont(13.5, .regular, relativeTo: .footnote)
                .foregroundStyle(StrandPalette.textSecondary)
        }
    }

    private func bpmFigure(leading: Bool) -> some View {
        CoachWorkoutFigure(value: LocalCoachCardFormat.whole(item.avgHr), label: "BPM",
                           tint: StrandPalette.textPrimary, leading: leading)
    }

    private func effortFigure(leading: Bool) -> some View {
        CoachWorkoutFigure(value: item.effort.map { UnitFormatter.effortDisplay($0, scale: effortScale) } ?? "—",
                           label: "STRAIN", tint: StrandPalette.strainAccent, leading: leading)
    }
}

private struct CoachWorkoutFigure: View {
    let value: String
    let label: LocalizedStringKey
    let tint: Color
    /// Left-aligned under the heading in the stacked row; right-aligned at the row's end otherwise.
    var leading = false

    var body: some View {
        VStack(alignment: leading ? .leading : .trailing, spacing: 0) {
            Text(value).coachFont(17, .semibold, relativeTo: .body, digits: true)
                .foregroundStyle(value == "—" ? StrandPalette.textTertiary : tint).lineLimit(1)
            Text(label).foregroundStyle(StrandPalette.textTertiary).microLabelFit(lines: 1, standardLines: 1)
        }
        .frame(minWidth: 40, alignment: leading ? .leading : .trailing)
    }
}

// MARK: - Stats

private struct CoachStatsCard: View {
    let card: LocalCoachCard.Stats

    private var symbol: String {
        card.title == "Recorded nutrition" ? "fork.knife" : "clock.arrow.circlepath"
    }

    var body: some View {
        CoachWidget(symbol: symbol, title: card.title, tint: .accent,
                    trailing: .record(date: card.day.map { LocalCoachCardFormat.dayLabel($0) }, isStale: card.isStale)) {
            CoachStatStrip(items: card.items.prefix(3).enumerated().map { index, item in
                CoachStat(id: index, label: LocalizedStringKey(item.label),
                          value: LocalCoachCardFormat.displayValue(item.value))
            })
        }
    }
}
#endif
